Assume that $\mathcal{Z}\in\mathbb{K}^{n_1 \times n_2 \times n_3}$ of tubal-rank $r$ satisfies the tensor $\mu_0$-incoherence condition and its compact t-SVD is given by $\mathcal{Z}=\mathcal{W} * \mathcal{S} * \mathcal{V}^{\top}$, where $\mathcal{W} \in \mathbb{K}^{n_1 \times r \times n_3}, \mathcal{S}\in \mathbb{K}^{r \times r \times n_3}$, and $\mathcal{V} \in \mathbb{K}^{n_2 \times r \times n_3}$. Suppose that $\Omega$ is generated according to the Bernoulli sampling model with probability $p$. 
Then tensor $\mathcal{Z}$ is the unique minimizer of  (16) if the following two conditions hold:
\begin{condition}
      $\left\|\mathcal{P}_{\mathbb{T}}\mathcal{R}_{\Omega}\mathcal{P}_{\mathbb{T}}-\mathcal{P}_{\mathbb{T}}\right\| \leq \frac{1}{2}$.
\end{condition}
\begin{condition}
      There exists a tensor $\mathcal{Y}$ such that $\mathcal{P}_{\Omega}(\mathcal{Y})=\mathcal{Y}$ and
\begin{enumerate}[ leftmargin=.5in]
    \item[(a)] $\left\|\mathcal{P}_{\mathbb{T}}(\mathcal{Y})-\mathcal{W}*\mathcal{V}^{\top}\right\|_{{\mathrm{F}}} \leq \frac{1}{4}\sqrt{\frac{p}{n_3}}$;
    \item[(b)] $\left\|\mathcal{P}_{\mathbb{T}^{\perp}}(\mathcal{Y})\right\|\leq \frac{1}{2}$.
\end{enumerate}
\end{condition}

There exists a tensor $\mathcal{Y}$ such that $\mathcal{P}_{\Omega}(\mathcal{Y})=\mathcal{Y}$ and
\begin{enumerate}[ leftmargin=.5in]
    \item[(a)] $\left\|\mathcal{P}_{\mathbb{T}}(\mathcal{Y})-\mathcal{W}*\mathcal{V}^{\top}\right\|_{{\mathrm{F}}} \leq \frac{1}{4}\sqrt{\frac{p}{n_3}}$;
    \item[(b)] $\left\|\mathcal{P}_{\mathbb{T}^{\perp}}(\mathcal{Y})\right\|\leq \frac{1}{2}$.
\end{enumerate}

\rm
Let $\mathcal{X}\in \mathbb{K}^{n_1\times n_2 \times n_3}.$  Assume that $\Omega$ is generated according to the Bernoulli distribution with probability $p$. Then, for any constant $c_2>1$,  
\begin{equation}\left\|\mathcal{R}_{\Omega}(\mathcal{X}) - \mathcal{X}\right\| \leq \sqrt{\frac{2c_2}{p}\log((n_1+n_2)n_3)}\|\mathcal{X}\|_{\infty,2}+\frac{c_2\log((n_1+n_2)n_3)}{p}\|\mathcal{X}\|_{\infty}
 \end{equation}
holds with probability at least $1-((n_1+n_2)n_3)^{1-c_2}$.

\rm
Let $\mathcal{Z}\in\mathbb{K}^{n_1 \times n_2 \times n_3}$ of tubal-rank $r$ satisfy the tensor $\mu_0$-incoherence condition. And its compact t-SVD is  $\mathcal{Z}=\mathcal{W} * \mathcal{S} * \mathcal{V}^{\top}$ where $\mathcal{W} \in \mathbb{K}^{n_1 \times r \times n_3}, \mathcal{S} \in \mathbb{K}^{r \times r \times n_3}$ and $\mathcal{V} \in \mathbb{K}^{n_2 \times r \times n_3}$. Suppose the entries in $\Omega$ are sampled according to the Bernoulli model with probability $p$.  If
\begin{equation}
p \geq \frac{256\beta(n_1+n_2)\mu_0r\log^2(n_1n_3+n_2n_3)}{n_1n_2} \text{~with~}\beta\geq 1,
\end{equation}
then $\mathcal{Z}$ is the unique minimizer to 

\begin{equation*}
\begin{gathered}
\min _{\mathcal{X}}\|\mathcal{X}\|_{\textnormal{TNN}}, ~
\textnormal{ subject to } \mathcal{P}_{\Omega}(\mathcal{X})=\mathcal{P}_{\Omega}(\mathcal{Z}),
\end{gathered}
\end{equation*}
 with probability at least $1- \frac{3\log(n_1n_3+n_2n_3)}{(n_1n_3+n_2n_3)^{4\beta-2}}$.
